        for (const link of this.onsc<IChannel>()) {
            if (!link.enabled) continue;
            const idx = links.indexOf(link);
            if (idx >= 0 && String(link.slot) === "output") session.publish(idx, output);
        }
    }
}

export function createGainNode(): GainNode {
    return new GainNode();
}

